// Looseleaf MP example app.
// Pages under pages/ are generated by `npm run build` from each component's
// _example/ dir — don't edit them by hand.
App({
  onLaunch() {
    // M0 spike: hand-drawn headline font (MIT, from upstream looseleaf).
    // Local package paths need base library >= 2.10.0. Failures are
    // non-fatal — components fall back to system fonts.
    wx.loadFontFace({
      global: true,
      family: 'Kevin Sans',
      source: 'url("/assets/fonts/KevinSans-Regular.woff2")',
      desc: { weight: 'normal' },
      fail: (e) => console.warn('[looseleaf] Kevin Sans regular failed to load', e),
    });
    wx.loadFontFace({
      global: true,
      family: 'Kevin Sans',
      source: 'url("/assets/fonts/KevinSans-Bold.woff2")',
      desc: { weight: 'bold' },
      fail: (e) => console.warn('[looseleaf] Kevin Sans bold failed to load', e),
    });
  },
});
